286	/** 解析最大采样间隔限制(正整数秒数);无效返回 null。 */
287	function parseMaxInterval(raw: string): number | null {
288	  const v = raw.trim();
289	  if (!/^\d+$/.test(v)) return null;
290	  const n = Number(v);
291	  if (!Number.isSafeInteger(n) || n < 1) return null;
292	  return n;
293	}
294	
295	/** 解析 --device/--from/--to(及允许时的 --tz、--max-interval)选项;出错返回错误消息字符串。 */
296	function parseOptions(rest: string[], allowTz = false, allowMaxInterval = false): ParsedOptions | string {
297	  const devices: string[] = [];
298	  let from: number | undefined;
299	  let to: number | undefined;
300	  let tz: string | undefined;
301	  let maxInterval: number | undefined;
302	  for (let i = 0; i < rest.length; i++) {
303	    let opt = rest[i];
304	    let value: string | undefined;
305	    const eq = opt.indexOf('=');
306	    if (opt.startsWith('--') && eq !== -1) {
307	      value = opt.slice(eq + 1);
308	      opt = opt.slice(0, eq);
309	    } else if (opt.startsWith('--')) {
310	      value = rest[i + 1];
311	      if (value === undefined) return `选项 '${opt}' 缺少值`;
312	      i++;
313	    } else {
314	      return `无法识别的参数 '${opt}'`;
315	    }
316	    if (opt === '--device') {
317	      if (value.trim() === '') return "'--device' 的值不能为空";
318	      devices.push(value);
319	    } else if (opt === '--from' || opt === '--to') {
320	      const ts = parseIso8601(value.trim());
321	      if (ts === null) {
322	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
323	      }
324	      if (opt === '--from') from = ts;
325	      else to = ts;
326	    } else if (opt === '--tz' && allowTz) {
327	      tz = value.trim();
328	      if (tz === '') return "'--tz' 的值不能为空";
329	    } else if (opt === '--max-interval' && allowMaxInterval) {
330	      const n = parseMaxInterval(value);
331	      if (n === null) {
332	        return `选项 '--max-interval' 的值无效: '${value.trim()}'(需正整数秒数)`;
333	      }
334	      maxInterval = n;
335	    } else {
336	      return `无法识别的选项 '${opt}'`;
337	    }
338	  }
339	  return { devices, from, to, tz, maxInterval };
340	}
341	
342	/** 校验 IANA 分日时区名;无效时返回错误消息字符串。 */
343	function checkTz(tz: string): string | null {
344	  if (loadTimezone(tz) === null) {
345	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
346	  }
347	  return null;
348	}
