350	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
351	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
352	  const out = new Map<string, string[]>();
353	  for (let i = 0; i < rest.length; i++) {
354	    let opt = rest[i];
355	    let value: string | undefined;
356	    const eq = opt.indexOf('=');
357	    if (opt.startsWith('--') && eq !== -1) {
358	      value = opt.slice(eq + 1);
359	      opt = opt.slice(0, eq);
360	    } else if (opt.startsWith('--')) {
361	      value = rest[i + 1];
362	      if (value === undefined) return `选项 '${opt}' 缺少值`;
363	      i++;
364	    } else {
365	      return `无法识别的参数 '${opt}'`;
366	    }
367	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
368	    const list = out.get(opt);
369	    if (list) list.push(value);
370	    else out.set(opt, [value]);
371	  }
372	  return out;
373	}
