375	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
376	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
377	  const list = flags.get(name);
378	  if (!list || list.length !== 1) return null;
379	  return list[0];
380	}
