382	/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
383	function dateFlag(value: string, label: string): { date: string } | string {
384	  const v = value.trim();
385	  if (parseUtcDate(v) === null) {
386	    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
387	  }
388	  return { date: v };
389	}
