391	function cmdRule(rest: string[]): number {
392	  const [sub, ...subrest] = rest;
393	  if (sub === 'list') {
394	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
395	    return cmdRuleList();
396	  }
397	  if (sub === 'create') {
398	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold', '--tz', '--max-interval']);
399	    if (typeof flags === 'string') return usageError(flags);
400	    const idRaw = oneFlag(flags, '--id');
401	    const deviceList = flags.get('--device');
402	    const groupList = flags.get('--group');
403	    const thresholdRaw = oneFlag(flags, '--threshold');
404	    const tzList = flags.get('--tz');
405	    const maxIntervalList = flags.get('--max-interval');
406	    if (idRaw === null || thresholdRaw === null) {
407	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
408	    }
409	    if (tzList !== undefined && tzList.length !== 1) {
410	      return usageError("'rule create' 的 --tz 只能出现一次");
411	    }
412	    if (maxIntervalList !== undefined && maxIntervalList.length !== 1) {
413	      return usageError("'rule create' 的 --max-interval 只能出现一次");
414	    }
415	    const hasDevice = deviceList !== undefined;
416	    const hasGroup = groupList !== undefined;
417	    if (hasDevice === hasGroup) {
418	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
419	    }
420	    if ((deviceList !== undefined && deviceList.length !== 1) ||
421	      (groupList !== undefined && groupList.length !== 1)) {
422	      return usageError("'rule create' 的目标选项只能出现一次");
423	    }
424	    const id = idRaw.trim();
425	    if (id === '') return usageError('规则标识不能为空');
426	    const thresholdMilli = parseKwh(thresholdRaw.trim());
427	    if (thresholdMilli === null) {
428	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
429	    }
430	    // 时区省略与显式 UTC 等价;按运行环境解析后的规范名存储与比较。
431	    let tz = 'UTC';
432	    if (tzList !== undefined) {
433	      const tzRaw = tzList[0].trim();
434	      if (tzRaw === '') return usageError("'--tz' 的值不能为空");
435	      const canonical = canonicalTimezone(tzRaw);
436	      if (canonical === null) {
437	        return usageError(`未知时区 '${tzRaw}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`);
438	      }
439	      tz = canonical;
440	    }
441	    // 采样间隔限制省略为无上限,创建后固定。
442	    let maxInterval: number | undefined;
443	    if (maxIntervalList !== undefined) {
444	      const parsed = parseMaxInterval(maxIntervalList[0]);
445	      if (parsed === null) {
446	        return usageError(`选项 '--max-interval' 的值无效: '${maxIntervalList[0].trim()}'(需正整数秒数)`);
447	      }
448	      maxInterval = parsed;
449	    }
450	    if (hasDevice) {
451	      const device = (deviceList as string[])[0].trim();
452	      if (device === '') return usageError("'--device' 的值不能为空");
453	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli, tz, maxInterval });
454	    }
455	    const group = (groupList as string[])[0].trim();
456	    if (group === '') return usageError("'--group' 的值不能为空");
457	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli, tz, maxInterval });
458	  }
459	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
460	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
461	}
