463	function cmdEvaluateEntry(rest: string[]): number {
464	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
465	  if (typeof flags === 'string') return usageError(flags);
466	  const ruleRaw = oneFlag(flags, '--rule');
467	  const fromRaw = oneFlag(flags, '--from');
468	  const toRaw = oneFlag(flags, '--to');
469	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
470	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
471	  }
472	  const ruleId = ruleRaw.trim();
473	  if (ruleId === '') return usageError('规则标识不能为空');
474	  const from = dateFlag(fromRaw, '起始日期');
475	  if (typeof from === 'string') return usageError(from);
476	  const to = dateFlag(toRaw, '结束日期');
477	  if (typeof to === 'string') return usageError(to);
478	  if (from.date >= to.date) return usageError('评估起日必须早于止日(--from < --to)');
479	  return cmdEvaluate({ ruleId, from: from.date, to: to.date });
480	}
