482	function cmdAlertsEntry(rest: string[]): number {
483	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
484	  if (typeof flags === 'string') return usageError(flags);
485	  const ruleRaw = oneFlag(flags, '--rule');
486	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
487	  const ruleId = ruleRaw.trim();
488	  if (ruleId === '') return usageError('规则标识不能为空');
489	  const fromList = flags.get('--from');
490	  const toList = flags.get('--to');
491	  if ((fromList !== undefined) !== (toList !== undefined)) {
492	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
493	  }
494	  let from: string | undefined;
495	  let to: string | undefined;
496	  if (fromList !== undefined) {
497	    const fromRaw = oneFlag(flags, '--from');
498	    const toRaw = oneFlag(flags, '--to');
499	    if (fromRaw === null || toRaw === null) {
500	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
501	    }
502	    const fromParsed = dateFlag(fromRaw, '起始日期');
503	    if (typeof fromParsed === 'string') return usageError(fromParsed);
504	    const toParsed = dateFlag(toRaw, '结束日期');
505	    if (typeof toParsed === 'string') return usageError(toParsed);
506	    if (fromParsed.date >= toParsed.date) return usageError('查询起日必须早于止日(--from < --to)');
507	    from = fromParsed.date;
508	    to = toParsed.date;
509	  }
510	  return cmdAlerts({ ruleId, from, to });
511	}
