588	    if (maxIntervalList !== undefined) {
589	      const parsed = parseMaxInterval(maxIntervalList[0]);
590	      if (parsed === null) {
591	        return usageError(`选项 '--max-interval' 的值无效: '${maxIntervalList[0].trim()}'(需正整数秒数)`);
592	      }
593	      maxInterval = parsed;
594	    }
595	    return cmdGroupDaily({ id, from, to, tz, maxInterval });
596	  }
597	  if (sub === 'schedule-report') {
598	    const flags = parseFlags(subrest, ['--id', '--schedule', '--from', '--to', '--tz', '--max-interval']);
599	    if (typeof flags === 'string') return usageError(flags);
600	    const idRaw = oneFlag(flags, '--id');
601	    const scheduleRaw = oneFlag(flags, '--schedule');
602	    const fromRaw = oneFlag(flags, '--from');
603	    const toRaw = oneFlag(flags, '--to');
604	    if (idRaw === null || scheduleRaw === null || fromRaw === null || toRaw === null) {
605	      return usageError("'group schedule-report' 需要 --id、--schedule、--from、--to 各恰好一个(起点含、终点不含)");
606	    }
607	    const tzList = flags.get('--tz');
608	    if (tzList !== undefined && tzList.length !== 1) {
609	      return usageError("'group schedule-report' 的 --tz 只能出现一次");
610	    }
611	    const maxIntervalList = flags.get('--max-interval');
612	    if (maxIntervalList !== undefined && maxIntervalList.length !== 1) {
613	      return usageError("'group schedule-report' 的 --max-interval 只能出现一次");
614	    }
615	    const id = idRaw.trim();
616	    if (id === '') return usageError('分组标识不能为空');
617	    if (scheduleRaw.trim() === '') return usageError("'--schedule' 的值不能为空");
618	    const from = parseIso8601(fromRaw.trim());
619	    if (from === null) {
620	      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
621	    }
622	    const to = parseIso8601(toRaw.trim());
623	    if (to === null) {
624	      return usageError(`选项 '--to' 的时间无效: '${toRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
625	    }
626	    if (from >= to) return usageError('查询起点必须早于终点(--from < --to)');
627	    let tz: string | undefined;
628	    if (tzList !== undefined) {
629	      tz = tzList[0].trim();
630	      if (tz === '') return usageError("'--tz' 的值不能为空");
631	      const bad = checkTz(tz);
632	      if (bad !== null) return usageError(bad);
633	    }
634	    let maxInterval: number | undefined;
635	    if (maxIntervalList !== undefined) {
636	      const parsed = parseMaxInterval(maxIntervalList[0]);
637	      if (parsed === null) {
638	        return usageError(`选项 '--max-interval' 的值无效: '${maxIntervalList[0].trim()}'(需正整数秒数)`);
639	      }
640	      maxInterval = parsed;
641	    }
642	    return cmdGroupScheduleReport({ id, schedulePath: scheduleRaw, from, to, tz, maxInterval });
643	  }
644	  if (sub === undefined) return usageError("'group' 需要子命令 configure、history、daily 或 schedule-report");
645	  return usageError(`无法识别的 group 子命令 '${sub}'`);
646	}
647	
648	/**
649	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
650	 * 各恰好一个。出错返回错误消息字符串。
651	 */
652	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
653	  const segments: string[][] = [[]];
654	  for (const tok of rest) {
655	    if (tok === '--item') segments.push([]);
656	    else segments[segments.length - 1].push(tok);
657	  }
658	  const headFlags = parseFlags(segments[0], ['--request']);
659	  if (typeof headFlags === 'string') return headFlags;
660	  const requestRaw = oneFlag(headFlags, '--request');
661	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
662	  const requestId = requestRaw.trim();
663	  if (requestId === '') return '请求标识不能为空';
664	  const itemSegs = segments.slice(1);
665	  if (itemSegs.length === 0) {
666	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
667	  }
668	  const items: CorrectionItem[] = [];
669	  for (const seg of itemSegs) {
670	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
671	    if (typeof flags === 'string') return flags;
672	    const deviceRaw = oneFlag(flags, '--device');
673	    const atRaw = oneFlag(flags, '--at');
674	    const expectRaw = oneFlag(flags, '--expect');
675	    const setRaw = oneFlag(flags, '--set');
676	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
677	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
678	    }
679	    const device = deviceRaw.trim();
680	    if (device === '') return "'--device' 的值不能为空";
681	    const ts = parseIso8601(atRaw.trim());
682	    if (ts === null) {
683	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
684	    }
685	    const expectedMilli = parseKwh(expectRaw.trim());
686	    if (expectedMilli === null) {
687	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
688	    }
689	    const replacementMilli = parseKwh(setRaw.trim());
690	    if (replacementMilli === null) {
691	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
692	    }
693	    items.push({ device, ts, expectedMilli, replacementMilli });
694	  }
695	  return { requestId, items };
696	}
697	
698	function cmdCorrectEntry(rest: string[]): number {
699	  const parsed = parseCorrectItems(rest);
700	  if (typeof parsed === 'string') return usageError(parsed);
701	  return cmdCorrect(parsed.requestId, parsed.items);
702	}
703	
704	function cmdUndoEntry(rest: string[]): number {
705	  const flags = parseFlags(rest, ['--request', '--target']);
706	  if (typeof flags === 'string') return usageError(flags);
707	  const requestRaw = oneFlag(flags, '--request');
708	  const targetRaw = oneFlag(flags, '--target');
709	  if (requestRaw === null || targetRaw === null) {
710	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
711	  }
712	  const requestId = requestRaw.trim();
713	  if (requestId === '') return usageError('撤销请求标识不能为空');
714	  const targetId = targetRaw.trim();
715	  if (targetId === '') return usageError('目标修正请求标识不能为空');
716	  return cmdUndo(requestId, targetId);
717	}
718	
719	function main(args: string[]): number {
720	  // 所有入口(含无参数、--help/-h、非法参数)都先取得数据目录操作权并处理
721	  // 未完成恢复,再执行查询或写入;协调失败返回 1,不输出正常业务结果。
722	  const result = withDirectoryCoordination<number>(() => runCommand(args));
723	  return typeof result === 'number' ? result : 1;
724	}
725	
726	function runCommand(args: string[]): number {
727	  if (args.length === 0) {
728	    console.log(help);
729	    return 0;
730	  }
731	  const [cmd, ...rest] = args;
732	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
733	    console.log(help);
734	    return 0;
735	  }
736	
737	  if (cmd === 'import') {
738	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
739	    return cmdImport(rest[0]);
740	  }
741	
742	  if (cmd === 'readings') {
743	    const parsed = parseOptions(rest);
744	    if (typeof parsed === 'string') return usageError(parsed);
745	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
746	      return usageError('查询起点必须早于终点(--from < --to)');
747	    }
748	    return cmdReadings(parsed);
749	  }
750	
751	  if (cmd === 'daily') {
752	    const parsed = parseOptions(rest, true, true);
753	    if (typeof parsed === 'string') return usageError(parsed);
754	    if (parsed.from === undefined || parsed.to === undefined) {
755	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
756	    }
757	    if (parsed.from >= parsed.to) {
758	      return usageError('查询起点必须早于终点(--from < --to)');
759	    }
760	    if (parsed.tz !== undefined) {
761	      const bad = checkTz(parsed.tz);
762	      if (bad !== null) return usageError(bad);
763	    }
764	    return cmdDaily({
765	      devices: parsed.devices,
766	      from: parsed.from,
767	      to: parsed.to,
768	      tz: parsed.tz,
769	      maxInterval: parsed.maxInterval,
770	    });
771	  }
772	
773	  if (cmd === 'rule') return cmdRule(rest);
774	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
775	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
776	  if (cmd === 'group') return cmdGroup(rest);
777	  if (cmd === 'correct') return cmdCorrectEntry(rest);
778	  if (cmd === 'undo') return cmdUndoEntry(rest);
779	
780	  if (cmd === 'corrections') {
781	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
782	    return cmdCorrections();
783	  }
784	
785	  if (cmd === 'ack') {
786	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
787	    const alertId = rest[0].trim();
788	    if (alertId === '') return usageError('告警标识不能为空');
789	    return cmdAck(alertId);
790	  }
791	
792	  if (cmd === 'backup') {
793	    if (rest.length !== 1) return usageError("'backup' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
794	    return cmdBackup(rest[0]);
795	  }
796	
797	  if (cmd === 'restore') {
798	    if (rest.length !== 1) return usageError("'restore' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
799	    return cmdRestore(rest[0]);
800	  }
801	
802	  return usageError(`无法识别的参数 '${cmd}'`);
803	}
804	
805	process.exitCode = main(process.argv.slice(2));
