73	export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';
74	
75	export interface AlertEvent {
76	  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
77	  seq: number;
78	  type: AlertEventType;
79	  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
80	  consumptionMilli?: string;
81	}
82	
83	export interface AlertRecord {
84	  /** 告警标识,全局唯一(设备与分组规则共用编号空间)。 */
85	  id: string;
86	  ruleId: string;
87	  /** 规则时区下的当地日期,YYYY-MM-DD(UTC 规则即 UTC 日期)。 */
88	  date: string;
89	  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
90	  status: 'triggered' | 'recovered';
91	  acknowledged: boolean;
92	  events: AlertEvent[];
93	}
94	
95	export interface AlertState {
96	  nextAlertNum: number;
97	  nextEventSeq: number;
98	  rules: AlertRule[];
99	  alerts: AlertRecord[];
100	}
101	
102	function err(message: string): void {
103	  console.error(`meterwatch: ${message}`);
104	}
105	
106	function emptyState(): AlertState {
107	  return { nextAlertNum: 1, nextEventSeq: 1, rules: [], alerts: [] };
108	}
109	
110	/** 目标在输出中的显示形式,如 device=meter-1 / group=floor-1。 */
111	function targetLabel(rule: Pick<AlertRule, 'targetType' | 'targetId'>): string {
112	  return `${rule.targetType}=${rule.targetId}`;
113	}
114	
115	/**
116	 * 解析告警存储的 JSON 结构。结构非法抛出 StoreError;source 用于错误消息
117	 * (如 `storage file <path>`)。旧版仅含 device 字段、无时区的规则按 UTC 读入。
118	 */
119	export function parseAlertState(data: unknown, source: string): AlertState {
120	  const bad = (what: string): StoreError =>
121	    new StoreError(`${source} is corrupted (${what})`);
122	  const o = data as Record<string, unknown>;
123	  if (o === null || typeof o !== 'object') throw bad('not an object');
124	  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
125	    throw bad('invalid nextAlertNum');
126	  }
127	  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
128	    throw bad('invalid nextEventSeq');
129	  }
130	  if (!Array.isArray(o.rules)) throw bad('missing rules array');
131	  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');
132	
133	  const ruleIds = new Set<string>();
134	  const rules: AlertRule[] = [];
135	  for (const r of o.rules as Array<Record<string, unknown>>) {
136	    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
137	    // 按损坏数据拒绝,不猜测原值。
138	    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
139	    if (
140	      r === null ||
141	      typeof r !== 'object' ||
142	      typeof r.id !== 'string' ||
143	      r.id.length === 0 ||
144	      thresholdMilli === null
145	    ) {
146	      throw bad('invalid rule entry');
147	    }
148	    // 目标类型:新版字段 targetType/targetId;旧版只有 device 字段,按 device 规则
149	    // 读入,已有设备规则无需手工转换即可继续使用。
150	    let targetType: RuleTargetType;
151	    let targetId: string;
152	    if (r.targetType === undefined) {
153	      if (typeof r.device !== 'string' || r.device.length === 0) throw bad('invalid rule entry');
154	      targetType = 'device';
155	      targetId = r.device;
156	    } else {
157	      if (r.targetType !== 'device' && r.targetType !== 'group') {
158	        throw bad(`invalid targetType in rule '${r.id}'`);
159	      }
160	      if (typeof r.targetId !== 'string' || r.targetId.length === 0) {
161	        throw bad(`invalid targetId in rule '${r.id}'`);
162	      }
163	      targetType = r.targetType;
164	      targetId = r.targetId;
165	    }
166	    // 时区:新版字段 tz 存规范 IANA 名;旧版无时区的规则按 UTC 使用。存储内
167	    // 非法时区按损坏数据拒绝,不能回退为 UTC;合法写法统一解析为规范名。
168	    let tz = 'UTC';
169	    if (r.tz !== undefined) {
170	      if (typeof r.tz !== 'string' || r.tz.length === 0) {
171	        throw bad(`invalid timezone in rule '${r.id}'`);
172	      }
173	      const canonical = canonicalTimezone(r.tz);
174	      if (canonical === null) throw bad(`invalid timezone in rule '${r.id}'`);
175	      tz = canonical;
176	    }
177	    // 采样间隔限制:新版字段 maxInterval 存正整数秒;旧版无该字段的规则按
178	    // 无上限使用。存储内非法限制按损坏数据拒绝,不能悄悄忽略。
179	    let maxInterval: number | undefined;
180	    if (r.maxInterval !== undefined) {
181	      if (!Number.isSafeInteger(r.maxInterval) || (r.maxInterval as number) < 1) {
182	        throw bad(`invalid maxInterval in rule '${r.id}'`);
183	      }
184	      maxInterval = r.maxInterval as number;
185	    }
186	    if (ruleIds.has(r.id)) throw bad(`duplicate rule id '${r.id}'`);
187	    ruleIds.add(r.id);
188	    rules.push({ id: r.id, targetType, targetId, thresholdMilli: thresholdMilli as bigint, tz, maxInterval });
189	  }
190	
191	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
192	  const alertIds = new Set<string>();
193	  for (const a of o.alerts as Array<Record<string, unknown>>) {
194	    const ok =
195	      a !== null &&
196	      typeof a === 'object' &&
197	      typeof a.id === 'string' &&
198	      a.id.length > 0 &&
199	      typeof a.ruleId === 'string' &&
200	      ruleIds.has(a.ruleId) &&
201	      typeof a.date === 'string' &&
202	      DATE_RE.test(a.date) &&
203	      (a.status === 'triggered' || a.status === 'recovered') &&
204	      typeof a.acknowledged === 'boolean' &&
205	      Array.isArray(a.events) &&
206	      (a.events as unknown[]).length > 0;
207	    if (!ok) throw bad('invalid alert entry');
208	    if (alertIds.has(a.id)) throw bad(`duplicate alert id '${a.id}'`);
209	    alertIds.add(a.id);
210	    const seqs = new Set<number>();
211	    for (const e of a.events as Array<Record<string, unknown>>) {
212	      const eok =
213	        e !== null &&
214	        typeof e === 'object' &&
215	        Number.isSafeInteger(e.seq) &&
216	        (e.seq as number) >= 1 &&
217	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
218	        (e.consumptionMilli === undefined ||
219	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
220	      if (!eok) throw bad('invalid alert event');
221	      if (seqs.has(e.seq as number)) throw bad(`duplicate event seq in alert '${a.id}'`);
222	      seqs.add(e.seq as number);
223	    }
224	  }
225	  return {
226	    nextAlertNum: o.nextAlertNum as number,
227	    nextEventSeq: o.nextEventSeq as number,
228	    rules,
229	    alerts: o.alerts as unknown as AlertRecord[],
230	  };
231	}
