233	/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
234	export function loadAlertState(path: string): AlertState {
235	  let text: string;
236	  try {
237	    text = readFileSync(path, 'utf8');
238	  } catch (e) {
239	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
240	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
241	  }
242	  let data: unknown;
243	  try {
244	    data = JSON.parse(text);
245	  } catch {
246	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
247	  }
248	  return parseAlertState(data, `storage file ${path}`);
249	}
250	
251	/** 序列化为告警存储文件的 JSON 结构(阈值为十进制字符串,任意大数精确)。 */
252	export function serializeAlertState(state: AlertState): Record<string, unknown> {
253	  return {
254	    version: 2,
255	    ...state,
256	    rules: state.rules.map((r) => ({
257	      id: r.id,
258	      targetType: r.targetType,
259	      targetId: r.targetId,
260	      thresholdMilli: r.thresholdMilli.toString(),
261	      tz: r.tz,
262	      ...(r.maxInterval !== undefined ? { maxInterval: r.maxInterval } : {}),
263	    })),
264	  };
265	}
266	
267	/**
268	 * 原子写入告警存储;失败抛错,原有数据保持不变。
269	 * 告警写入不触碰读数与成员版本文件。
270	 */
271	function saveAlertState(path: string, state: AlertState): void {
272	  mkdirSync(dirname(path), { recursive: true });
273	  const tmp = `${path}.tmp-${process.pid}`;
274	  const body = JSON.stringify(serializeAlertState(state), null, 2) + '\n';
275	  try {
276	    writeFileSync(tmp, body, 'utf8');
277	    renameSync(tmp, path);
278	  } catch (e) {
279	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
280	  }
281	}
282	
283	/**
284	 * 载入读数并取出指定设备的完整时序(按时刻排序)。
285	 * 同设备同一实际时刻存在多条存储记录时抛 StoreError。
286	 */
287	function deviceSeries(device: string): Reading[] {
288	  const all = loadStore(dataFilePath());
289	  const series = all.filter((r) => r.device === device).sort((a, b) => a.ts - b.ts);
290	  for (let i = 1; i < series.length; i++) {
291	    if (series[i].ts === series[i - 1].ts) {
292	      throw new StoreError(
293	        `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(series[i].ts)}`,
294	      );
295	    }
296	  }
297	  return series;
298	}
299	
300	/**
301	 * 分组规则的评估环境:绑定分组与全库设备时序。
302	 * 读取读数时拒绝全库重复身份,包括不属于该分组的设备。
303	 */
304	interface GroupEnv {
305	  kind: 'group';
306	  group: Group;
307	  byDevice: Map<string, Reading[]>;
308	}
309	
310	interface DeviceEnv {
311	  kind: 'device';
312	  series: Reading[];
313	}
314	
315	type RuleEnv = DeviceEnv | GroupEnv;
316	
317	/** 为规则准备评估环境;未知分组或存储损坏抛 StoreError。 */
318	function prepareEnv(rule: AlertRule): RuleEnv {
319	  if (rule.targetType === 'device') {
320	    return { kind: 'device', series: deviceSeries(rule.targetId) };
321	  }
322	  const groups = loadGroups(groupFilePath());
323	  const group = groups.find((g) => g.id === rule.targetId);
324	  if (!group) {
325	    throw new StoreError(
326	      `unknown group '${rule.targetId}' bound by rule '${rule.id}' (groups storage has no such group)`,
327	    );
328	  }
329	  const byDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
330	  return { kind: 'group', group, byDevice };
331	}
332	
333	/** 一天的有效/异常/未知覆盖秒数后缀;采用间隔限制时附上过长间隔造成的未知秒数。 */
334	function coverageSuffix(
335	  stats: Pick<DayStats, 'valid' | 'anomaly' | 'unknown' | 'gapUnknown'>,
336	  limited: boolean,
337	): string {
338	  const base = `valid=${stats.valid}s anomaly=${stats.anomaly}s unknown=${stats.unknown}s`;
339	  return limited ? `${base} gap=${stats.gapUnknown}s` : base;
340	}
341	
342	/** 一天各实际 UTC 时段的展示行(时段按实际时刻升序)。 */
343	function periodLines(day: LocalDay): string[] {
344	  return day.periods.map((p) => `    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
345	}
346	
347	/** 一天内过长区间明细的展示行(指出相关设备与原始相邻读数时刻)。 */
348	function gapLines(stats: Pick<DayStats, 'gaps'>, rule: AlertRule): string[] {
349	  return stats.gaps.map((g) => formatGapLine(g, rule.targetType === 'device' ? rule.targetId : undefined));
350	}
351	
352	/** 规则时区的墙钟格式化器;存储载入时已校验,此处不会失败。 */
353	function ruleFormat(rule: AlertRule): Intl.DateTimeFormat {
354	  const fmt = loadTimezone(rule.tz);
355	  if (fmt === null) {
356	    throw new StoreError(`rule '${rule.id}' has invalid timezone '${rule.tz}' in storage`);
357	  }
358	  return fmt;
359	}
360	
361	/**
362	 * 计算规则在一个当地日期上的统计:汇总归属该日期的全部实际 UTC 时段。
363	 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径;
364	 * 日界线与成员切换都不重置各设备原读数区间的分摊起点。
365	 * maxInterval 为规则固定的采样间隔限制(省略为无上限)。
366	 */
367	function computeRuleDay(env: RuleEnv, day: LocalDay, maxInterval?: number): DayStats {
368	  let valid = 0;
369	  let anomaly = 0;
370	  let unknown = 0;
371	  let gapUnknown = 0;
372	  const gaps: GapDetail[] = [];
373	  let consumption = 0n;
374	  for (const p of day.periods) {
375	    if (env.kind === 'device') {
376	      const s = computeDay(env.series, p.start, p.end, maxInterval);
377	      valid += s.valid;
378	      anomaly += s.anomaly;
379	      unknown += s.unknown;
380	      gapUnknown += s.gapUnknown;
381	      mergeGaps(gaps, s.gaps);
382	      consumption += s.consumption;
383	    } else {
384	      const s = computeGroupSegment(env.group.versions, env.byDevice, p.start, p.end, maxInterval);
385	      valid += s.valid;
386	      anomaly += s.anomaly;
387	      unknown += s.unknown;
388	      gapUnknown += s.gapUnknown;
389	      mergeGaps(gaps, s.gaps);
390	      consumption += s.consumption;
391	    }
392	  }
393	  return { valid, anomaly, unknown, gapUnknown, gaps, consumption };
394	}
