396	/**
397	 * 创建规则。相同标识、同目标类型、同目标标识、等价阈值、同时区(规范名)
398	 * 及同采样间隔限制重试成功且不重复创建;任一不同即报冲突。设备必须已有
399	 * 存储读数;分组必须已配置。返回进程退出码。
400	 */
401	export function cmdRuleCreate(opts: {
402	  id: string;
403	  targetType: RuleTargetType;
404	  targetId: string;
405	  thresholdMilli: bigint;
406	  /** 规范 IANA 时区名(调用方已解析;省略时传 'UTC')。 */
407	  tz: string;
408	  /** 最大采样间隔限制(正整数秒);省略表示无上限,创建后固定。 */
409	  maxInterval?: number;
410	}): number {
411	  const statePath = alertFilePath();
412	  let state: AlertState;
413	  try {
414	    state = loadAlertState(statePath);
415	  } catch (e) {
416	    if (e instanceof StoreError) {
417	      err(e.message);
418	      return 1;
419	    }
420	    throw e;
421	  }
422	
423	  const got = `${opts.targetType}=${opts.targetId}`;
424	  const existing = state.rules.find((r) => r.id === opts.id);
425	  if (existing) {
426	    if (
427	      existing.targetType === opts.targetType &&
428	      existing.targetId === opts.targetId &&
429	      existing.thresholdMilli === opts.thresholdMilli &&
430	      existing.tz === opts.tz &&
431	      existing.maxInterval === opts.maxInterval
432	    ) {
433	      console.log(
434	        `rule '${opts.id}' already exists with identical parameters (${targetLabel(existing)} ` +
435	          `threshold=${formatKwh(existing.thresholdMilli)} kWh tz=${existing.tz} ` +
436	          `max-interval=${maxIntervalText(existing.maxInterval)}); unchanged`,
437	      );
438	      return 0;
439	    }
440	    err(
441	      `rule '${opts.id}' already exists with different parameters ` +
442	        `(stored ${targetLabel(existing)} threshold=${formatKwh(existing.thresholdMilli)} kWh ` +
443	        `tz=${existing.tz} max-interval=${maxIntervalText(existing.maxInterval)}, ` +
444	        `got ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh ` +
445	        `tz=${opts.tz} max-interval=${maxIntervalText(opts.maxInterval)}); conflict`,
446	    );
447	    return 1;
448	  }
449	
450	  // 目标存在性:设备需已有存储读数;分组需已配置(配置时已保证成员设备存在)。
451	  try {
452	    if (opts.targetType === 'device') {
453	      const devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
454	      if (!devices.has(opts.targetId)) {
455	        err(`unknown device '${opts.targetId}': no stored readings; import readings before creating a rule`);
456	        return 1;
457	      }
458	    } else {
459	      const groups = loadGroups(groupFilePath());
460	      if (!groups.some((g) => g.id === opts.targetId)) {
461	        err(`unknown group '${opts.targetId}': configure the group before creating a rule`);
462	        return 1;
463	      }
464	    }
465	  } catch (e) {
466	    if (e instanceof StoreError) {
467	      err(e.message);
468	      return 1;
469	    }
470	    throw e;
471	  }
472	
473	  state.rules.push({
474	    id: opts.id,
475	    targetType: opts.targetType,
476	    targetId: opts.targetId,
477	    thresholdMilli: opts.thresholdMilli,
478	    tz: opts.tz,
479	    maxInterval: opts.maxInterval,
480	  });
481	  try {
482	    saveAlertState(statePath, state);
483	  } catch (e) {
484	    if (e instanceof StoreError) {
485	      err(e.message);
486	      return 1;
487	    }
488	    throw e;
489	  }
490	  console.log(
491	    `rule '${opts.id}' created: ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh ` +
492	      `tz=${opts.tz} max-interval=${maxIntervalText(opts.maxInterval)}`,
493	  );
494	  return 0;
495	}
