524	/**
525	 * 评估规则在连续完整当地日期范围 [from, to)(规则时区的 YYYY-MM-DD,起日含、
526	 * 止日不含)上的超限情况。每个日期统计归属该日期的全部实际 UTC 时段,一次
527	 * 评估只作一次判定;整日被跳过的日期标明跳过,不判定、不创建也不恢复告警。
528	 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途任一存储
529	 * 或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
530	 */
531	export function cmdEvaluate(opts: { ruleId: string; from: string; to: string }): number {
532	  const statePath = alertFilePath();
533	  let state: AlertState;
534	  let rule: AlertRule;
535	  let env: RuleEnv;
536	  let fmt: Intl.DateTimeFormat;
537	  try {
538	    state = loadAlertState(statePath);
539	    const found = state.rules.find((r) => r.id === opts.ruleId);
540	    if (!found) {
541	      err(`unknown rule '${opts.ruleId}'`);
542	      return 1;
543	    }
544	    rule = found;
545	    env = prepareEnv(rule);
546	    fmt = ruleFormat(rule);
547	  } catch (e) {
548	    if (e instanceof StoreError) {
549	      err(e.message);
550	      return 1;
551	    }
552	    throw e;
553	  }
554	
555	  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
556	  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
557	  const alertIds = new Set(state.alerts.map((a) => a.id));
558	
559	  const threshold = rule.thresholdMilli;
560	  const limited = rule.maxInterval !== undefined;
561	  const lines: string[] = [];
562	  for (const { label, day } of localDateRange(fmt, opts.from, opts.to)) {
563	    if (day === null) {
564	      // 整日被跳过(无实际时段):不判定、不触发也不恢复。
565	      lines.push(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})  no alert action`);
566	      continue;
567	    }
568	    const stats = computeRuleDay(env, day, rule.maxInterval);
569	    const coverage = coverageSuffix(stats, limited);
570	    if (stats.unknown > 0 || stats.anomaly > 0) {
571	      // 有未知或下降覆盖:不可判定,不触发也不恢复。
572	      lines.push(`  ${label}  undecidable (${coverage})  no alert action`);
573	      lines.push(...periodLines(day));
574	      lines.push(...gapLines(stats, rule));
575	      continue;
576	    }
577	    const exceeded = stats.consumption > threshold;
578	    const cmp =
579	      `consumption=${formatKwh(stats.consumption)} kWh ` +
580	      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
581	    const open = state.alerts.find(
582	      (a) => a.ruleId === rule.id && a.date === label && a.status === 'triggered',
583	    );
584	    if (exceeded) {
585	      if (open) {
586	        // 重复超限:保留原标识,不新增事件。
587	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered  ${coverage}`);
588	      } else {
589	        const id = `alert-${state.nextAlertNum++}`;
590	        if (alertIds.has(id)) {
591	          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
592	          return 1;
593	        }
594	        alertIds.add(id);
595	        state.alerts.push({
596	          id,
597	          ruleId: rule.id,
598	          date: label,
599	          status: 'triggered',
600	          acknowledged: false,
601	          events: [
602	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
603	          ],
604	        });
605	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)  ${coverage}`);
606	      }
607	    } else {
608	      if (open) {
609	        open.status = 'recovered';
610	        open.events.push({
611	          seq: state.nextEventSeq++,
612	          type: 'recovered',
613	          consumptionMilli: stats.consumption.toString(),
614	        });
615	        lines.push(`  ${label}  ${cmp}  NORMAL  alert ${open.id} recovered  ${coverage}`);
616	      } else {
617	        lines.push(`  ${label}  ${cmp}  NORMAL  no alert  ${coverage}`);
618	      }
619	    }
620	    lines.push(...periodLines(day));
621	  }
622	
623	  try {
624	    saveAlertState(statePath, state);
625	  } catch (e) {
626	    if (e instanceof StoreError) {
627	      err(e.message);
628	      return 1;
629	    }
630	    throw e;
631	  }
632	
633	  console.log(
634	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  ` +
635	      `tz=${rule.tz}  max-interval=${maxIntervalText(rule.maxInterval)}`,
636	  );
637	  for (const line of lines) console.log(line);
638	  return 0;
639	}
640	
641	/**
642	 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
643	 * 给定日期范围时按规则时区的当地日期逐日展示当前计算的消耗或不可判定原因、
644	 * 实际 UTC 时段与各次告警;省略范围时展示有告警记录的全部日期。触发/恢复
645	 * 事件中的消耗为评估当时记录,不随后续数据变化改写。返回进程退出码。
646	 */
647	export function cmdAlerts(opts: { ruleId: string; from?: string; to?: string }): number {
648	  let state: AlertState;
649	  let rule: AlertRule;
650	  let env: RuleEnv;
651	  let fmt: Intl.DateTimeFormat;
652	  try {
653	    state = loadAlertState(alertFilePath());
654	    const found = state.rules.find((r) => r.id === opts.ruleId);
655	    if (!found) {
656	      err(`unknown rule '${opts.ruleId}'`);
657	      return 1;
658	    }
659	    rule = found;
660	    env = prepareEnv(rule);
661	    fmt = ruleFormat(rule);
662	  } catch (e) {
663	    if (e instanceof StoreError) {
664	      err(e.message);
665	      return 1;
666	    }
667	    throw e;
668	  }
669	
670	  // 待展示的当地日期(升序):给定范围时为范围内全部日期;省略范围时为有告警
671	  // 记录的全部日期。
672	  let labels: string[];
673	  if (opts.from !== undefined && opts.to !== undefined) {
674	    labels = localDateRange(fmt, opts.from, opts.to).map((e) => e.label);
675	  } else {
676	    labels = [
677	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
678	    ].sort();
679	  }
680	
681	  console.log(
682	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  ` +
683	      `tz=${rule.tz}  max-interval=${maxIntervalText(rule.maxInterval)}`,
684	  );
685	  if (labels.length === 0) {
686	    console.log(`  no alerts recorded for rule '${rule.id}'`);
687	    return 0;
688	  }
689	
690	  // 各当地日期的实际 UTC 时段;整日被跳过的日期为 null。日历日期逐日递增,
691	  // 末日后延一天作为切分终点。
692	  const last = parseUtcDate(labels[labels.length - 1]) as number;
693	  const endLabel = formatIsoUtc(last + DAY_SECONDS).slice(0, 10);
694	  const byLabel = new Map<string, LocalDay | null>();
695	  for (const e of localDateRange(fmt, labels[0], endLabel)) byLabel.set(e.label, e.day);
696	
697	  const threshold = rule.thresholdMilli;
698	  const limited = rule.maxInterval !== undefined;
699	  for (const label of labels) {
700	    const day = byLabel.get(label) ?? null;
701	    if (day === null) {
702	      console.log(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})`);
703	    } else {
704	      const stats = computeRuleDay(env, day, rule.maxInterval);
705	      if (stats.unknown > 0 || stats.anomaly > 0) {
706	        console.log(`  ${label}  undecidable (${coverageSuffix(stats, limited)})`);
707	      } else {
708	        const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
709	        console.log(
710	          `  ${label}  consumption=${formatKwh(stats.consumption)} kWh ` +
711	            `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)  ${coverageSuffix(stats, limited)}`,
712	        );
713	      }
714	      for (const line of periodLines(day)) console.log(line);
715	      for (const line of gapLines(stats, rule)) console.log(line);
716	    }
717	    const alerts = state.alerts
718	      .filter((a) => a.ruleId === rule.id && a.date === label)
719	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
720	    if (alerts.length === 0) {
721	      console.log('    no alerts');
722	      continue;
723	    }
724	    for (const a of alerts) {
725	      console.log(
726	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
727	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
728	      );
729	      const events = a.events
730	        .map((e) => {
731	          const consumption =
732	            e.consumptionMilli !== undefined
733	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
734	              : '';
735	          return `#${e.seq} ${e.type}${consumption}`;
736	        })
737	        .join(', ');
738	      console.log(`      events: ${events}`);
739	    }
740	  }
741	  return 0;
742	}
743	
744	/**
745	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
746	 * 确认不改变超限或恢复状态。返回进程退出码。
747	 */
748	export function cmdAck(alertId: string): number {
749	  const statePath = alertFilePath();
750	  let state: AlertState;
751	  try {
752	    state = loadAlertState(statePath);
753	  } catch (e) {
754	    if (e instanceof StoreError) {
755	      err(e.message);
756	      return 1;
757	    }
758	    throw e;
759	  }
760	  const alert = state.alerts.find((a) => a.id === alertId);
761	  if (!alert) {
762	    err(`unknown alert '${alertId}'`);
763	    return 1;
764	  }
765	  if (alert.acknowledged) {
766	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
767	    return 0;
768	  }
769	  alert.acknowledged = true;
770	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
771	  try {
772	    saveAlertState(statePath, state);
773	  } catch (e) {
774	    if (e instanceof StoreError) {
775	      err(e.message);
776	      return 1;
777	    }
778	    throw e;
779	  }
780	  const rule = state.rules.find((r) => r.id === alert.ruleId);
781	  const target = rule ? ` ${targetLabel(rule)}` : '';
782	  console.log(
783	    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
784	  );
785	  return 0;
786	}
787

