32	  loadGroups,
33	  type Group,
34	} from './groups.ts';
35	
36	function err(message: string): void {
37	  console.error(`meterwatch: ${message}`);
38	}
39	
40	export interface ScheduleWindow {
41	  /** 开始星期,0=周日 .. 6=周六。 */
42	  startDow: number;
43	  /** 开始当日的起始分钟,0..1439。 */
44	  startMin: number;
45	  /** 相对开始日的结束分钟(不含),恒大于 startMin;结束早于开始时 +1440 跨至下一日。 */
46	  endMin: number;
47	}
48	
49	const DOW_BY_NAME: Record<string, number> = {
50	  sun: 0,
51	  mon: 1,
52	  tue: 2,
53	  wed: 3,
54	  thu: 4,
55	  fri: 5,
56	  sat: 6,
57	};
58	
59	/** 解析 HH:mm 为当日分钟数;allow24 时另接受 24:00(=1440)。无效返回 null。 */
60	function parseHm(raw: string, allow24: boolean): number | null {
61	  const m = /^(\d{2}):(\d{2})$/.exec(raw);
62	  if (!m) return null;
63	  const h = Number(m[1]);
64	  const mi = Number(m[2]);
65	  if (mi > 59) return null;
66	  if (h > 23) {
67	    if (allow24 && h === 24 && mi === 0) return 1440;
68	    return null;
69	  }
70	  return h * 60 + mi;
71	}
72	
73	/**
74	 * 解析每周运行时间表文本。每行一个窗口:<星期> <开始 HH:mm> <结束 HH:mm>;
75	 * 空行与 # 之后的注释忽略。星期为 mon..sun(不区分大小写)。开始限
76	 * 00:00-23:59,结束另可 24:00;同值起止拒绝;结束早于开始跨至下一日。
77	 * 重叠或重复窗口不在此拒绝,分类时取并集。非法时返回错误消息字符串。
78	 */
79	export function parseSchedule(text: string): ScheduleWindow[] | string {
80	  const windows: ScheduleWindow[] = [];
81	  const lines = text.split(/\r\n|\r|\n/);
82	  for (let i = 0; i < lines.length; i++) {
83	    const hash = lines[i].indexOf('#');
84	    const line = (hash === -1 ? lines[i] : lines[i].slice(0, hash)).trim();
85	    if (line === '') continue;
86	    const where = `line ${i + 1}`;
87	    const parts = line.split(/\s+/);
88	    if (parts.length !== 3) {
89	      return `${where}: expect '<weekday> <start HH:mm> <end HH:mm>' (weekday: mon..sun)`;
90	    }
91	    const dow = DOW_BY_NAME[parts[0].toLowerCase()];
92	    if (dow === undefined) {
93	      return `${where}: unknown weekday '${parts[0]}' (expect mon, tue, wed, thu, fri, sat or sun)`;
94	    }
95	    const start = parseHm(parts[1], false);
96	    if (start === null) {
97	      return `${where}: invalid start time '${parts[1]}' (expect HH:mm within 00:00-23:59)`;
98	    }
99	    const end = parseHm(parts[2], true);
100	    if (end === null) {
101	      return `${where}: invalid end time '${parts[2]}' (expect HH:mm within 00:00-24:00)`;
102	    }
103	    if (end === start) {
104	      return `${where}: start and end must differ (both are '${parts[1]}')`;
105	    }
106	    // 结束早于开始即跨至下一日,尾段沿用开始日规则(周日可跨至周一)。
107	    const endMin = end < start ? end + 1440 : end;
108	    windows.push({ startDow: dow, startMin: start, endMin });
109	  }
110	  return windows;
111	}
112	
113	interface Period {
114	  /** 时段起点(含),epoch 秒。 */
115	  start: number;
116	  /** 时段终点(不含),epoch 秒。 */
117	  end: number;
118	}
119	
120	/** 墙钟午夜(按 UTC 解释的 epoch 秒)对应的星期,0=周日。1970-01-01 为周四。 */
121	function dowOfNaive(naiveMidnight: number): number {
122	  const days = Math.floor(naiveMidnight / 86400);
123	  return (((days + 4) % 7) + 7) % 7;
124	}
125	
126	/**
127	 * 把 [from, to) 按每周时间表分为运行与非运行两类实际 UTC 时段,两类合计
128	 * 恰好等于查询范围(每秒只属一类)。分类按实际时刻的当地日期与墙钟:
129	 * 墙钟段切分自命名时区(段内偏移恒定、当地日期单一),窗口墙钟区间与段
130	 * 墙钟区间求交后换算回 UTC;夏令时跳过的墙钟没有实际时刻,不虚构覆盖,
131	 * 回拨重复的墙钟两段实际时段各自分类,不套固定偏移或日长。
132	 */
133	export function classifyPeriods(
134	  fmt: Intl.DateTimeFormat,
135	  from: number,
136	  to: number,
137	  windows: ScheduleWindow[],
138	): { running: Period[]; nonRunning: Period[] } {
139	  const raw: Period[] = [];
140	  if (windows.length > 0) {
141	    // 各当地日期生效的窗口墙钟区间(按墙钟午夜缓存):本日开始的窗口,以及
142	    // 上一日开始、跨至本日的窗口尾段。
143	    const wallByDate = new Map<string, Array<[number, number]>>();
144	    const wallIntervalsOf = (label: string): Array<[number, number]> => {
145	      const cached = wallByDate.get(label);
146	      if (cached) return cached;
147	      const dayNaive = parseUtcDate(label) as number;
148	      const wall: Array<[number, number]> = [];
149	      for (const w of windows) {
150	        for (const startNaive of [dayNaive, dayNaive - 86400]) {
151	          if (dowOfNaive(startNaive) !== w.startDow) continue;
152	          wall.push([startNaive + w.startMin * 60, startNaive + w.endMin * 60]);
153	        }
154	      }
155	      wallByDate.set(label, wall);
156	      return wall;
157	    };
158	    for (const seg of wallSegments(fmt, from, to)) {
159	      const wall = wallIntervalsOf(seg.label);
160	      if (wall.length === 0) continue;
161	      // 段内偏移恒定,墙钟区间随 UTC 线性平移。
162	      const ws = seg.start + seg.offset;
163	      const we = seg.end + seg.offset;
164	      for (const [a, b] of wall) {
165	        const lo = Math.max(a, ws);
166	        const hi = Math.min(b, we);
167	        if (lo < hi) raw.push({ start: lo - seg.offset, end: hi - seg.offset });
168	      }
169	    }
170	    raw.sort((a, b) => a.start - b.start);
171	  }
172	  // 重叠或重复窗口取并集。
173	  const running: Period[] = [];
174	  for (const r of raw) {
175	    const last = running[running.length - 1];
176	    if (last && r.start <= last.end) {
177	      if (r.end > last.end) last.end = r.end;
178	    } else {
179	      running.push({ start: r.start, end: r.end });
180	    }
181	  }
182	  const nonRunning: Period[] = [];
183	  let cursor = from;
184	  for (const r of running) {
185	    if (cursor < r.start) nonRunning.push({ start: cursor, end: r.start });
186	    cursor = r.end;
187	  }
188	  if (cursor < to) nonRunning.push({ start: cursor, end: to });
189	  return { running, nonRunning };
190	}
191	
192	/**
193	 * 分组运行/非运行时段能耗报表:按本地每周运行时间表把 [from, to) 分为
194	 * 两类时段,分别按当时生效成员核查能耗。只读,不写入数据。返回进程退出码。
195	 */
196	export function cmdGroupScheduleReport(opts: {
197	  id: string;
198	  /** 本地每周运行时间表文件路径(只读)。 */
199	  schedulePath: string;
200	  from: number;
201	  to: number;
202	  /** 解释时间表的 IANA 时区;省略为 UTC。 */
203	  tz?: string;
204	  /** 最大采样间隔限制(正整数秒);省略表示无上限。只影响本次查询结果。 */
205	  maxInterval?: number;
206	}): number {
207	  const tzName = opts.tz ?? 'UTC';
208	  const tz = loadTimezone(tzName);
209	  if (!tz) {
210	    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
211	    return 2;
212	  }
213	
214	  let text: string;
215	  try {
216	    text = readFileSync(opts.schedulePath, 'utf8');
217	  } catch (e) {
218	    err(`cannot read schedule file ${opts.schedulePath}: ${(e as Error).message}`);
219	    return 1;
220	  }
221	  const parsed = parseSchedule(text);
222	  if (typeof parsed === 'string') {
223	    err(`invalid schedule file ${opts.schedulePath}: ${parsed}`);
224	    return 2;
225	  }
226	  const windows = parsed;
227	
228	  let groups: Group[];
229	  try {
230	    groups = loadGroups(groupFilePath());
231	  } catch (e) {
232	    if (e instanceof StoreError) {
233	      err(e.message);
234	      return 1;
235	    }
236	    throw e;
237	  }
238	  const group = groups.find((g) => g.id === opts.id);
239	  if (!group) {
240	    err(`unknown group '${opts.id}'`);
241	    return 1;
242	  }
243	
244	  let seriesByDevice: Map<string, Reading[]>;
245	  try {
246	    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
247	  } catch (e) {
248	    if (e instanceof StoreError) {
249	      err(e.message);
250	      return 1;
251	    }
252	    throw e;
253	  }
254	
255	  const { running, nonRunning } = classifyPeriods(tz, opts.from, opts.to, windows);
256	
257	  console.log(`group: ${group.id}`);
258	  console.log(`schedule: ${opts.schedulePath} (${windows.length} window(s))`);
259	  console.log(`timezone: ${tzName}`);
260	  console.log(`max-interval: ${maxIntervalText(opts.maxInterval)}`);
261	
262	  const classes: Array<{ name: string; periods: Period[] }> = [
263	    { name: 'running', periods: running },
264	    { name: 'non-running', periods: nonRunning },
265	  ];
266	  let incomplete = false;
267	  const coverage: number[] = [];
268	  for (const c of classes) {
269	    let valid = 0;
270	    let anomaly = 0;
271	    let unknown = 0;
272	    let gapUnknown = 0;
273	    const gaps: GapDetail[] = [];
274	    let consumption = 0n;
275	    for (const p of c.periods) {
276	      const stats = computeGroupSegment(
277	        group.versions,
278	        seriesByDevice,
279	        p.start,
280	        p.end,
281	        opts.maxInterval,
282	      );
283	      valid += stats.valid;
284	      anomaly += stats.anomaly;
285	      unknown += stats.unknown;
286	      gapUnknown += stats.gapUnknown;
287	      mergeGaps(gaps, stats.gaps);
288	      consumption += stats.consumption;
289	    }
290	    let seconds = 0;
291	    for (const p of c.periods) seconds += p.end - p.start;
292	    coverage.push(seconds);
293	    const classIncomplete = anomaly > 0 || unknown > 0;
294	    if (classIncomplete) incomplete = true;
295	
296	    const consumptionText =
297	      valid > 0
298	        ? `consumption=${formatKwh(consumption)} kWh (estimate)`
299	        : 'consumption=n/a (no valid coverage)';
300	    let line =
301	      `  class=${c.name}  ${consumptionText}` +
302	      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
303	    if (opts.maxInterval !== undefined) line += `  gap=${gapUnknown}s`;
304	    if (classIncomplete) line += '  INCOMPLETE';
305	    console.log(line);
306	    for (const p of c.periods) {
307	      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
308	    }
309	    for (const g of gaps) {
310	      console.log(formatGapLine(g));
311	    }
312	  }
313	
314	  const status = incomplete
315	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
316	    : 'status=complete';
317	  console.log(
318	    `  summary: group=${group.id}  running=${coverage[0]}s  non-running=${coverage[1]}s` +
319	      `  total=${opts.to - opts.from}s  ${status}`,
320	  );
321	  return 0;
322	}
