    const s = m;
    while (m < WEEK_MINUTES && covered[m] === 1) m++;
    const startDow = Math.floor(s / 1440);
    out.push({ startDow, startMin: s - startDow * 1440, endMin: m - startDow * 1440 });
  }
  return out;
}

