    if (tzRaw === '') return usageError("'--tz' 的值不能为空");
    const canonical = canonicalTimezone(tzRaw);
    if (canonical === null) {
      return usageError(`未知时区 '${tzRaw}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`);
    }
    tz = canonical;
  }
